#include <iostream>
#include <map>
#include <string>


int main() {
    int n{};if(!(std::cin>>n)||n<0||n>100)return 1;std::map<std::string,int> m;for(int i=0;i<n;++i){std::string k;int v;if(!(std::cin>>k>>v))return 1;m.insert_or_assign(k,v);}for(const auto& [k,v]:m)std::cout<<k<<' '<<v<<'\n';
}
